def test_gdn_store_shards_round_trip_in_both_tp_directions(monkeypatch, conv_layout):
    monkeypatch.setenv("VLLM_SSM_CONV_STATE_LAYOUT", conv_layout)
    _assert_state_store_round_trip(_make_gdn_store_layout)

