        for expected in ((0, False), (16, False)):
            deadline = time.monotonic() + 5
            result = scheduler.get_num_new_matched_tokens(request, 0)
            while result == (None, False) and time.monotonic() < deadline:
                time.sleep(0.01)
                result = scheduler.get_num_new_matched_tokens(request, 0)
            assert result == expected
            handle.hits = [True]
    finally:
        scheduler.close()

